/* Lot 98: a value composited on the value below (wf_cssprop_add) (generated by scripts/lot98_animgen.py; expectations from scripts/lot98_animmodel.py). */
#include "../../framework/unity.h"
#include <string.h>
#include "wf_cssprop.h"

static wf_cssprop_t g_p;
static char g_o[160];

static int syn(const char *s) {
    memset(&g_p, 0, sizeof(g_p));
    g_p.syntax = (unsigned char)wf_cssprop_syntax_parse(s, (int)strlen(s), &g_p);
    return g_p.syntax != 0;
}

/* the sum text; the return code is checked against code */
static const char *ad(const char *s, const char *under, const char *v, int code) {
    if (!syn(s)) return "BAD SYNTAX";
    if (wf_cssprop_add(&g_p, under, v, g_o, (int)sizeof(g_o)) != code) return "BAD CODE";
    return g_o;
}

static void test_l98_add_0(void) {
    TEST_ASSERT_EQUAL_STRING("627.9deg", ad("'<percentage> | <angle>'", "-37%", "627.9deg", 1));
    TEST_ASSERT_EQUAL_STRING("111 -213", ad("'<integer>+'", "236 304 -477", "111 -213", 1));
    TEST_ASSERT_EQUAL_STRING("calc(193.32% - 23.96px)", ad("'<length-percentage>'", "calc(96% - 124.3px)", "calc(97.32% + 100.34px)", 2));
    TEST_ASSERT_EQUAL_STRING("calc(-99.9% + 91.5689px)", ad("'<length-percentage>'", "91.5689px", "-99.9%", 2));
    TEST_ASSERT_EQUAL_STRING("gamma", ad("'<custom-ident>'", "gamma", "gamma", 1));
    TEST_ASSERT_EQUAL_STRING("-457.257", ad("'<number>'", "-636.2", "178.943", 2));
    TEST_ASSERT_EQUAL_STRING("4px", ad("'<length>#'", "12.24px, 88.068px, -2.35px", "4px", 1));
    TEST_ASSERT_EQUAL_STRING("250.625%", ad("'<length-percentage>'", "52.116%", "198.509%", 2));
    TEST_ASSERT_EQUAL_STRING("-613.4 1125.3", ad("'<number>+'", "-168.4 746", "-445 379.3", 2));
    TEST_ASSERT_EQUAL_STRING("251", ad("'<time># | <number>'", "15.02s, 4.84s", "251", 1));
}

